const emails = [];
for (const item of $input.all()) {
  const j = item.json;
  const from = j.From || j.from || (j.headers && j.headers.from) || '';
  const subject = j.Subject || j.subject || (j.headers && j.headers.subject) || '';
  let text = j.text || j.textPlain || '';
  if (!text && j.html) text = String(j.html).replace(/<[^>]+>/g, ' ');
  if (!text) text = j.snippet || '';
  const dateRaw = j.date || j.internalDate || j.Date;
  let received_at;
  if (dateRaw) {
    const n = Number(dateRaw);
    received_at = new Date(isNaN(n) ? dateRaw : n).toISOString();
  } else {
    received_at = new Date().toISOString();
  }
  emails.push({ gmail_msg_id: j.id || j.messageId, sender: from, subject, text, received_at });
}
return [{ json: { emails } }];
